mapper.select:
/* User04Mapper.selectApprovalCandidates */ SELECT U.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , U.RANK_CD AS rankCd , FNC_CMM_INFO_SRCH(U.CMPNY_CD, 'BAIM_VAL', U.RANK_CD, 'COM007') AS rankNm , D.SORT_IDX AS rankSortIdx , U.AUTH_CD AS authCd , FNC_CMM_INFO_SRCH(U.CMPNY_CD, 'BAIM_VAL', U.AUTH_CD, 'COM005') AS authNm , AD.SORT_IDX AS authSortIdx , FNC_CMM_INFO_SRCH(U.CMPNY_CD, 'NODE', U.SITE_CD, U.NODE_CD) AS nodeNm FROM TB_USER U LEFT JOIN TB_BAIM_VAL_D D ON D.CMPNY_CD = U.CMPNY_CD AND D.BAIM_VAL_CD = 'COM007' AND D.BAIM_VAL_D_CD = U.RANK_CD AND D.USE_YN = 'Y' LEFT JOIN TB_BAIM_VAL_D AD ON AD.CMPNY_CD = U.CMPNY_CD AND AD.BAIM_VAL_CD = 'COM005' AND AD.BAIM_VAL_D_CD = U.AUTH_CD AND AD.USE_YN = 'Y' WHERE U.CMPNY_CD = #{cmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL AND U.ACCOUNT_STATUS = '01' AND U.USER_CD != #{excludeUserCd} AND U.AUTH_CD != 'system'
AND U.NODE_CD = #{nodeCd}
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
ORDER BY (AD.SORT_IDX IS NULL), AD.SORT_IDX ASC, (D.SORT_IDX IS NULL), D.SORT_IDX ASC, U.USER_ID ASC

/* User04Mapper.selectPresetMasters */
SELECT
      P.PRESET_ID   AS presetId
    , P.PRESET_NM   AS presetNm
    , P.DEFAULT_YN  AS defaultYn
  FROM TB_APRV_LINE_PRESET P
 WHERE P.CMPNY_CD = #{cmpnyCd}
   AND P.USER_CD  = #{userCd}
   AND P.USE_YN   = 'Y'
 ORDER BY (P.DEFAULT_YN = 'Y') DESC, P.PRESET_NM ASC, P.PRESET_ID ASC

/* User04Mapper.selectPresetOwner */
SELECT P.USER_CD
  FROM TB_APRV_LINE_PRESET P
 WHERE P.CMPNY_CD = #{cmpnyCd}
   AND P.PRESET_ID = #{presetId}
   AND P.USE_YN = 'Y'
 LIMIT 1

/* User04Mapper.selectPresetDefaultYn */
SELECT P.DEFAULT_YN
  FROM TB_APRV_LINE_PRESET P
 WHERE P.CMPNY_CD  = #{cmpnyCd}
   AND P.PRESET_ID = #{presetId}
   AND P.USE_YN    = 'Y'
 LIMIT 1

/* User04Mapper.selectNextPresetId */
SELECT CONCAT('P', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'APRV_PRESET_ID'))
  FROM DUAL

/* User04Mapper.countActiveCandidate */
SELECT COUNT(*)
  FROM TB_USER U
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.SITE_CD  = #{siteCd}
   AND U.USER_CD  = #{userCd}
   AND U.USE_YN   = 'Y'
   AND U.WITHDRAWAL_DATE IS NULL
   AND U.ACCOUNT_STATUS  = '01'
   AND U.AUTH_CD != 'system'

mapper.insert:
/* User04Mapper.insertPresetMaster */
INSERT INTO TB_APRV_LINE_PRESET (
      CMPNY_CD, PRESET_ID, USER_CD, PRESET_NM, DEFAULT_YN, USE_YN, INSERT_NO, INSERT_DATE
) VALUES (
      #{cmpnyCd}, #{presetId}, #{userCd}, #{presetNm}, #{defaultYn}, 'Y', #{insertNo}, NOW()
)

mapper.update:
/* User04Mapper.updatePresetMaster */
UPDATE TB_APRV_LINE_PRESET
   SET PRESET_NM   = #{presetNm}
     , DEFAULT_YN  = #{defaultYn}
     , UPDATE_NO   = #{updateNo}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD  = #{cmpnyCd}
   AND PRESET_ID = #{presetId}

