/* User04Mapper.insertPresetStep */
INSERT INTO TB_APRV_LINE_PRESET_D (
      CMPNY_CD, PRESET_ID, STEP_NO, APPROVER_USER_CD, INSERT_NO, INSERT_DATE
) VALUES (
      #{cmpnyCd}, #{presetId}, #{stepNo}, #{approverUserCd}, #{insertNo}, NOW()
)

