/* User04Mapper.deletePresetSteps */
DELETE FROM TB_APRV_LINE_PRESET_D
 WHERE CMPNY_CD = #{cmpnyCd}
   AND PRESET_ID = #{presetId}

/* User04Mapper.deletePresetMaster */
DELETE FROM TB_APRV_LINE_PRESET
 WHERE CMPNY_CD = #{cmpnyCd}
   AND PRESET_ID = #{presetId}

mapper.update:
/* User04Mapper.clearDefaultForUser */
UPDATE TB_APRV_LINE_PRESET
   SET DEFAULT_YN = 'N'
 WHERE CMPNY_CD = #{cmpnyCd}
   AND USER_CD  = #{userCd}
   AND DEFAULT_YN = 'Y'

/* User04Mapper.setDefault */
UPDATE TB_APRV_LINE_PRESET
   SET DEFAULT_YN  = 'Y'
     , UPDATE_NO   = #{updateNo}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD  = #{cmpnyCd}
   AND PRESET_ID = #{presetId}
